INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "秦宗权", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的秦宗权，在此段中为遣兵者。", "biography": null, "status": "draft", "id": "4ab9b100-f137-522e-9b11-1ef372de9edf"}, {"name": "陈敬瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年记载的陈敬瑄：此前许诺以东川酬赏高仁厚。", "biography": null, "status": "draft", "id": "ad1f9c74-f6fd-50ff-b6c3-679c0c591a71"}, {"name": "郑绍业", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：郑绍业。", "biography": null, "status": "draft", "id": "e0ded02a-9a47-5c45-b733-64ee0b6e4b49"}, {"name": "申屠琮", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：申屠琮。", "biography": null, "status": "draft", "id": "2885a483-ea4e-52db-b299-e3fc1add8a83"}, {"name": "黄巢", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "晚唐起兵者。朱温早年在其军中，曾受命驻守东渭桥并招降诸葛爽。", "biography": "晚唐起兵者。朱温早年在其军中，曾受命驻守东渭桥并招降诸葛爽。", "status": "draft", "id": "f1a6e500-8866-5790-8423-7db3ce39a131"}, {"name": "朱敬玫", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：朱敬玫。", "biography": null, "status": "draft", "id": "3c56096f-fa21-5230-9fa6-de66fede10a9"}, {"name": "陈儒", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的陈儒，在此段中为攻舒州者。", "biography": null, "status": "draft", "id": "ac890eb1-fc70-5b5d-8d09-41f0b4bb8d6c"}, {"name": "程君之", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：程君之。", "biography": null, "status": "draft", "id": "09aec1aa-b67c-5ba8-8633-a43456356f76"}, {"name": "雷满", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：雷满。", "biography": null, "status": "draft", "id": "19c1c2db-ebbf-5810-9588-c9c0bcc44cbc"}, {"name": "张瑰", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：张瑰。", "biography": null, "status": "draft", "id": "0a92bc80-c524-5b52-96b0-bcb5553c2046"}, {"name": "韩师德", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：韩师德。", "biography": null, "status": "draft", "id": "76902c15-c389-51b0-a1bc-4e671b70f241"}, {"name": "高骈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的高骈，在此段中为受呈者。", "biography": null, "status": "draft", "id": "c4d5b35a-b520-57df-87da-baff9480b7e4"}, {"name": "杨玄晦", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：杨玄晦。", "biography": null, "status": "draft", "id": "b956d8d4-f4ce-597c-a9ed-350fef7426d4"}, {"name": "成汭", "aliases": ["郭禹"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：成汭。", "biography": null, "status": "draft", "id": "c476a6a9-2254-5cdf-b51d-55a7f49d0dd8"}, {"name": "卢光稠", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：卢光稠。", "biography": null, "status": "draft", "id": "8cce49d0-02a5-5169-a977-e1d7b17c58aa"}, {"name": "谭全播", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：谭全播。", "biography": null, "status": "draft", "id": "31e0ab36-725e-5765-a161-a66ff1c8843e"}, {"name": "王绪", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：王绪。", "biography": null, "status": "draft", "id": "9fbf20bd-aa87-55f6-8b18-40577932c72a"}, {"name": "刘行全", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启元年条所见人物：刘行全。", "biography": null, "status": "draft", "id": "598ab61e-1796-5dec-8a17-8677