ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朝廷下诏招抚秦宗权", "start_year": 885, "end_year": 885, "time_original": "光启元年正月戊午", "dynasty": "唐", "description": "朝廷下诏招抚秦宗权。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "a072052e-a768-5952-8bc1-c1efda15054f"}, {"title": "僖宗车驾离开成都", "start_year": 885, "end_year": 885, "time_original": "光启元年正月己卯", "dynasty": "唐", "description": "皇帝车驾离成都，陈敬瑄送至汉州后返回。", "phases": [], "location_name": "成都、汉州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "506ac196-a3c0-5a3a-a317-b244995b3b79"}, {"title": "申屠琮先前率兵赴长安讨黄巢", "start_year": null, "end_year": null, "time_original": "郑绍业镇荆南时；确年待考", "dynasty": "唐", "description": "郑绍业镇荆南期间曾遣申屠琮率兵五千至长安攻击黄巢。", "phases": [], "location_name": "荆南、长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "571e50f0-9b44-5ad8-a1e3-ba0325c92be2"}, {"title": "程君之率忠勇军逃往朗州，申屠琮追击", "start_year": null, "end_year": null, "time_original": "申屠琮回荆南后；确年待考", "dynasty": "唐", "description": "忠勇军行为暴横。陈儒请申屠琮处理；程君之闻讯率众奔朗州，申屠琮追击，杀百余人，余众溃散。", "phases": [], "location_name": "荆南、朗州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "31d1922d-1f41-531a-b18b-82da00453b17"}, {"title": "雷满屡攻荆南，陈儒纳赂退敌", "start_year": null, "end_year": null, "time_original": "光启元年前后屡次；确年待考", "dynasty": "唐", "description": "雷满多次攻掠荆南，陈儒用重赂使其退去。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e12c89b9-fd4b-5ecf-ab8e-2e07f40823f3"}, {"title": "张瑰、韩师德叛高骈并据复、岳州", "start_year": 885, "end_year": 885, "time_original": "光启元年条；具体月日未载", "dynasty": "唐", "description": "张瑰与韩师德叛离高骈，占据复州、岳州并自称刺史；陈儒请二人摄荆南军职，拟用以击雷满。", "phases": [], "location_name": "复州、岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "43d912c2-505b-5838-9afa-0bdfcc5122d3"}, {"title": "张瑰逐陈儒并将其囚禁", "start_year": 885, "end_year": 885, "time_original": "张瑰、韩师德受邀后；具体日未载", "dynasty": "唐", "description": "韩师德引兵入峡劫掠，张瑰返回荆南逐陈儒并取代之；陈儒欲奔行在，被张瑰挟回囚禁。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7b0431d3-79c8-5b20-a82e-d36e1c805e2e"}, {"title": "朱敬玫先前杀将夺财，朝廷遣杨玄晦代之", "start_year": null, "end_year": null, "time_original": "“先是”追叙；确年待考", "dynasty": "唐", "description": "《通鉴》追叙朱敬玫先前多次杀将及富商夺财，朝廷遣杨玄晦接替其职位。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9bedf868-8737-51be-b6d1-19746b242650"}, {"title": "张瑰杀朱敬玫夺其财物", "start_year": 885, "end_year": 885, "time_original": "杨玄晦代朱敬玫后；具体日未载", "dynasty": "唐", "description": "朱敬玫留居荆南，张瑰遣兵夜攻并杀之，夺其财物。", "phases": [], "location_name": "荆南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3a65df3c-8a24-54d0-9d73-fda5aa07d078"}, {"title": "成汭以郭禹之名据归州", "start_year": 885, "end_year": 885, "time_original": "光启元年庚申；月份依本段未明", "dynasty": "唐", "description": "郭禹原名成汭，因先前杀人改名；张瑰欲杀他，郭禹率众出走，庚申袭据归州，自称刺史。", "phases": [], "location_name": "归州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8c311eef-a4a9-5053-a675-d29ceaf0666d"}, {"title": "卢光稠陷虔州并用谭全播为谋主", "start_year": 885, "end_year": 885, "time_original": "光启元年条；具体月日未载", "dynasty": "唐", "description": "卢光稠攻陷虔州并自称刺史，以同乡谭全播为谋主。", "phases": [], "location_name": "虔州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b0ffb3ec-e388-5314-aed1-a5a44045a4c5"}, {"title": "王绪惧秦宗权，率光寿兵渡江", "start_year": 885, "end_year": 885, "time_original": "光启元年正月条；具体日未载", "dynasty": "唐", "description": "秦宗权向光州刺史王绪索租赋，王绪无法缴纳；秦宗权发兵。王绪遂率光、寿兵渡江，驱使吏民随行，以刘行全为前锋，转掠江、洪、虔州。", "phases": [], "location_name": "光州、寿州、江南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1237f823-6e1b-5364-8be4-fe993648f695"}, {"title": "王绪部攻陷汀、漳而未守住", "start_year": 885, "end_year": 885, "time_original": "光启元年正月（“是月”）", "dynasty": "唐", "description": "王绪部当月攻陷汀、漳二州，但未能据守。", "phases": [], "location_name": "汀州、漳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "00ba73e5-9acf-56c6-95d0-4ca92653bdf3"}, {"title": "朱全忠于焦夷败秦宗权", "start_year": 885, "end_year": 885, "time_original": "光启元年正月后条；具体日未载", "dynasty": "唐", "description": "秦宗权侵颍、亳；朱全忠在焦夷击败其军。", "phases": [], "location_name": "焦夷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c3c88e94-d554-5079-b218-716bfe2b8f5c"}, {"title": "僖宗车驾抵凤翔", "start_year": 885, "end_year": 885, "time_original": "光启元年二月丙申", "dynasty": "唐", "description": "皇帝车驾抵达凤翔。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1ba928f7-4a25-560a-a554-dbadcba58ce1"}, {"title": "僖宗车驾返回长安", "start_year": 885, "end_year": 885, "time_original": "光启元年三月丁卯", "dynasty": "唐", "description": "皇帝车驾返回京师长安；《通鉴》记城内荒废。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "85740308-b364-5ed5-a7e7-e163604e08f0"}, {"title": "朝廷赦天下、改元光启", "start_year": 885, "end_year": 885, "time_original": "光启元年三月己巳", "dynasty": "唐", "description": "朝廷赦天下并改元光启。", "phases": [], "location_name": "长安", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "77dab18b-e173-5c09-a9ee-cc7b21d6c5dc"}, {"title": "秦宗权称帝并置百官", "start_year": 885, "end_year": 885, "time_original": "光启元年三月条；具体日未载", "dynasty": "唐", "description": "秦宗权称帝，设百官。", "phases": [], "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "11d6ecad-e5af-5679-ad31-2473247b8bdd"}, {"title": "时溥受命统兵讨秦宗权", "start_year": 885, "end_year": 885, "time_original": "秦宗权称帝后；具体日未载", "dynasty": "唐", "description": "朝廷任时溥为蔡州四面行营兵马都统，令其讨伐秦宗权。", "phases": [], "location_name": "蔡州方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e5d7fa7d-fc5e-51e5-9423-523ea01f8925"}]'::jsonb)
